style.css:
@-moz-document domain("soundcloud.com") {
/* Set background to a soft baby pink */
  body {
    background-color: #ffe6f0 !important;
  }

  /* Change header and navigation bar to a lighter pink */
  header, .header__content, .sidebar {
    background-color: #ffccd9 !important;
  }

  /* Style for buttons and links */
  a, button {
    color: #d6336c !important;
    font-weight: bold;
  }

  /* Remove clutter and keep it minimal */
  .soundTitle__title,
  .playbackSound__title,
  .sound__footer,
  .queue,
  .waveform {
    background: transparent !important;
    box-shadow: none !important;
  }

  /* Player controls */
  .playControl {
    background-color: #ffd1dc !important;
    border-radius: 50%;
  }

  /* Highlight progress bar in pink */
  .seekbar__progress {
    background-color: #ff66b2 !important;
  }

  /* Remove unnecessary borders and shadows */
  * {
    border: none !important;
    box-shadow: none !important;
  }
}
